/* Presentation and interaction layer. Existing data services and API contracts remain intact. */
let overviewMode='Retention',modelTab='Performance',churnTab='Analysis',reportChoice='summary',cohortMode='purchase',filtersExpanded=false;
let recentQueries=getStore('queries',[]),reportHistory=getStore('report-history',[]);
colors.High='#b66b54';colors.Critical='#a84543';colors.Medium='#b59b58';colors.Low='#628c79';colors.Unscored='#c5c9c3';
function tabs(items,active,variable){return `<div class="section-tabs" role="tablist">${items.map(n=>`<button role="tab" aria-selected="${n===active}" class="${n===active?'selected':''}" onclick="${variable}='${n}';renderContent()">${n}</button>`).join('')}</div>`}
function dateControl(){return `<select class="date-select" aria-label="Reporting period" onchange="period=Number(this.value);renderContent()">${[30,60,90,180,365].map(n=>`<option value="${n}" ${period===n?'selected':''}>Last ${n} days</option>`).join('')}</select>`}
header=function(title,sub,actions=true){return `<div class="page-head"><div><div class="eyebrow">MAN MATTERS / RETENTION WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="actions">${dateControl()}<button onclick="exportReport('summary')">Export report <span aria-hidden="true">↗</span></button></div>`:''}</div>`};
shell=function(){document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-icon">${navIcon(2)}</span><span class="brand-text">Retention<span class="brand-second">Radar</span></span></div><button class="collapse-btn" aria-label="Collapse sidebar" onclick="document.body.classList.toggle('collapsed');this.setAttribute('aria-expanded',!document.body.classList.contains('collapsed'))">‹</button><div class="workspace"><span class="mm">m.</span><div><strong>Man Matters</strong><small>Customer intelligence</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.filter(n=>n!=='Settings').map((n,i)=>`${i===8?'<div class="nav-label nav-divider">GOVERNANCE</div>':''}<button title="${n}" aria-current="${view===n?'page':'false'}" class="${view===n?'active':''}" onclick="navigate('${n}')"><span class="nav-icon">${navIcon(i)}</span><span class="label">${n}</span>${n==='Retention Actions'?`<span class="count">${interventions.filter(x=>!['Resolved','Unsuccessful'].includes(x.status)).length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><button class="settings-link" title="Settings" onclick="navigate('Settings')">${navIcon(10)}<span class="label">Workspace settings</span></button><div class="user"><span class="avatar">AS</span><div><strong>Ananya Sharma</strong><small>${esc(settings.role)}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb-group"><button class="mobile-menu" aria-label="Toggle navigation" onclick="document.body.classList.toggle('show-menu')">☰</button><span class="breadcrumb">Workspace <span class="slash">/</span> <b>${view}</b></span></div><div class="top-actions"><input aria-label="Global customer search" placeholder="Search customers…" onkeydown="if(event.key==='Enter'){query=this.value;navigate('Customer Intelligence',true)}"><span class="workspace-status"><i></i>Demo workspace</span></div></header><div class="demo"><span class="demo-label">SYNTHETIC DATA</span><span>A demonstration workspace. No actual Man Matters customer records.</span><span>Snapshot · 01 Nov 2026</span></div><section class="content" id="content"></section></main>`;renderContent()};
function summaryMetric(label,value,detail,change=null){return `<div class="summary-metric"><span class="metric-name">${label}</span><strong>${value}</strong><span class="metric-context">${change==null?'':`<em class="${change<0?'negative':''}">${change>=0?'+':''}${change.toFixed(1)}%</em> `}${detail}</span></div>`}
function compareChange(a,b){return b?(a-b)/b*100:0}
function compactDistribution(list){const total=list.length;return `<div class="distribution-stack">${Object.keys(colors).map(k=>{let n=list.filter(c=>c.risk===k).length;return `<button style="width:${n/total*100}%;background:${colors[k]}" aria-label="${k}: ${n} customers" title="${k}: ${fmt(n)} customers" onclick="riskFilter='${k}';navigate('Customer Intelligence',true)"></button>`}).join('')}</div><div class="distribution-rows">${Object.keys(colors).map(k=>{const n=list.filter(c=>c.risk===k).length;return `<button onclick="riskFilter='${k}';navigate('Customer Intelligence',true)"><span><i style="background:${colors[k]}"></i>${k==='Unscored'?'Outside model population':k+' risk'}</span><b>${fmt(n)}</b><small>${pct(n/total)}</small></button>`}).join('')}</div>`}
function overviewDesign(){const list=scoped(),m=metrics(list),previous=metrics(list,new Date(date(D.asOf)-period*86400000).toISOString().slice(0,10)),trend=series(list).slice(-Math.max(2,Math.min(7,Math.ceil(period/30)))),alerts=[...list].filter(c=>c.probability!=null).sort((a,b)=>b.probability*b.revenue-a.probability*a.revenue).slice(0,5);const key=overviewMode==='Retention'?'retention':'churn';return header('Retention overview','Customer health, commercial exposure, and where to act next.')+`<div class="scope-bar"><span><i class="live-dot"></i> Snapshot as of 01 Nov 2026</span><span>Comparison: ${period} days earlier</span><select aria-label="Overview product filter" onchange="productFilter=this.value;renderContent()"><option value="">All products</option>${D.products.map(p=>`<option value="${p.id+1}" ${productFilter===String(p.id+1)?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="metric-band">${summaryMetric('Active customers',fmt(m.active),'vs prior snapshot',compareChange(m.active,previous.active))}${summaryMetric('Customers at risk',fmt(m.riskn),'High + critical model risk')}${summaryMetric('Predicted inactivity',pct(m.pred),'30-day horizon · scored customers')}${summaryMetric('Revenue exposure',money(m.atrisk),'Risk-weighted historical value')}</div><div class="supporting-metrics"><span>Retention <b>${pct(m.retention)}</b></span><span>Repeat purchase <b>${pct(m.repeat)}</b></span><span>Historical value / customer <b>${money(m.clv)}</b></span><button onclick="openDefinitions()">Metric definitions</button></div><div class="executive-grid"><section class="chart-section"><div class="section-heading"><div><h2>Customer health over time</h2><p>Monthly observed refill status · ${fmt(list.length)} customers</p></div></div>${tabs(['Retention','Inactivity'],overviewMode,'overviewMode')}${lineChart(trend,[key],['#35786e'])}<div class="chart-caption">${overviewMode==='Retention'?'Purchasers within':'Purchasers beyond'} product replenishment cycle + grace. Hover a point for its value.</div></section><aside class="risk-section"><div class="section-heading"><div><h2>Risk composition</h2><p>Current model snapshot</p></div><span class="small-count">${fmt(list.length)}</span></div>${compactDistribution(list)}<p class="forecast-note">Already-inactive customers are outside the incident-risk model. No comparable prior score snapshot exists.</p></aside></div><div class="priority-strip"><span class="priority-number">${fmt(m.riskn)}</span><div><h3>customers to keep on your radar</h3><p>Prioritise by predicted risk and historical customer value.</p></div><button class="primary" onclick="navigate('Customer Intelligence');riskFilter='High';renderContent()">Review customer queue <span>↗</span></button></div><div class="lower-grid">${customerTable(alerts,'Priority customers','Ranked by probability × historical revenue',false,true)}<section class="product-watch"><div class="section-heading"><div><h2>Product retention</h2><p>Observed customer health by category</p></div></div>${D.products.map(p=>{const cs=list.filter(c=>c.product===p.id),v=metrics(cs).retention;return `<button class="product-track" onclick="productFilter='${p.id+1}';navigate('Customer Intelligence',true)"><span>${p.name}</span><b>${pct(v)}</b><i><em style="width:${v*100}%"></em></i></button>`}).join('')}<button class="link-btn" onclick="navigate('Product Analytics')">Compare products ↗</button></section></div><details class="detail-section"><summary>Revenue exposure by product</summary>${barChart(list,'exposure')}<p class="forecast-note">Historical customer value weighted by model probability. This is exposure, not forecast lost or recovered revenue.</p></details>`}
function openDefinitions(){openDrawer(`<div class="drawer-head"><h2>Metric definitions</h2><button onclick="closeDrawer()">Close</button></div>${recordTable([{Metric:'Active',Definition:'Last completed order within product cycle plus grace.'},{Metric:'At risk',Definition:'High or critical probability among eligible active purchasers.'},{Metric:'Predicted inactivity',Definition:'Mean calibrated 30-day probability among scored customers.'},{Metric:'Revenue exposure',Definition:'Historical value × probability for high/critical customers; not forecast loss.'},{Metric:'Historical customer value',Definition:'Observed completed-order revenue per purchaser, not predicted lifetime value.'},{Metric:'Comparison',Definition:'Observed metrics compare the selected period’s opening and closing snapshots. Prior model scores are unavailable.'}])}`)}
const previousWorkspace=workspaceV2;
function customersDesign(){let html=previousWorkspace();html=html.replace('<div class="filters">',`<details class="filter-panel" ${filtersExpanded?'open':''} ontoggle="filtersExpanded=this.open"><summary>Search & advanced filters <span>${filtered().length.toLocaleString()} matching customers</span></summary><div class="filters">`).replace('<div class="workbar">','</details><div class="workbar">');return html}
function segmentsDesign(){const segments=['New','Active','Consistent','At-Risk','Dormant','Recovered','High-Value'],all=metrics(customers).rev;return header('Customer segments','Different behaviours deserve different retention strategies.',false)+`<div class="scope-bar"><span>${fmt(customers.length)} customers</span><span>Six lifecycle groups · one overlapping value segment</span></div><section class="ledger"><div class="section-heading"><h2>Segment portfolio</h2><span class="muted">Select a segment to explore its customers</span></div><div class="table-wrap"><table class="segment-table"><thead><tr><th>Segment</th><th>Customers</th><th>Revenue contribution</th><th>Retention</th><th>Repeat purchase</th><th></th></tr></thead><tbody>${segments.map((name,i)=>{const cs=customers.filter(c=>name==='High-Value'?c.revenue>=5000:c.stage===name),m=metrics(cs);return `<tr tabindex="0" onclick="segmentFilter='${name}';navigate('Customer Intelligence',true)" onkeydown="if(event.key==='Enter')this.click()"><td><span class="segment-index">0${i+1}</span><b>${name.replace('-',' ')} customers</b></td><td>${fmt(cs.length)}</td><td><span class="revenue-amount">${money(m.rev)}</span><span class="inline-track"><i style="width:${m.rev/all*100}%"></i></span><small>${pct(m.rev/all)}</small></td><td>${pct(m.retention)}</td><td>${pct(m.repeat)}</td><td>↗</td></tr>`}).join('')}</tbody></table></div></section><div class="method-note"><b>How to read this view</b><p>Lifecycle groups follow New → Dormant → At-Risk → Recovered → Consistent → Active. High-value includes customers with ₹5,000+ observed revenue and overlaps lifecycle segments.</p></div>`}
const oldActions=actionsV2;
function actionsDesign(){const html=oldActions();if(actionView==='table'){const original=interventionCentre();return header('Retention actions','A shared queue for timely, accountable customer follow-up.',false)+tabs(['board','table'],actionView,'actionView')+original.slice(original.indexOf('<div class="metrics">'))}return html.replace('<div class="workbar">','<div class="workbar action-toolbar">')}
function campaignsDesign(){return header('Campaign intelligence','Compare outreach strategies and inspect their observed results.',false)+`<div class="section-heading"><div class="section-tabs"><span class="selected">All campaigns <small>${campaigns.length}</small></span></div><button class="primary" onclick="campaignForm()">Create campaign</button></div><div class="method-note compact"><b>Simulated execution</b><span>No messages are sent. Incremental effectiveness is unmeasured; there is no control group.</span></div><div class="table-wrap ledger"><table><thead><tr><th>Campaign / strategy</th><th>Status</th><th>Targeted</th><th>Contact rate</th><th>Click-through</th><th>Reorder rate</th><th>Revenue</th><th></th></tr></thead><tbody>${campaigns.map(c=>`<tr><td><b>${esc(c.name)}</b><small class="cell-meta">${esc(c.type)} · ${c.risk} risk</small></td><td><span class="badge">${c.status}</span></td><td>${c.status==='Draft'?'—':fmt(c.targeted)}</td><td>${c.status==='Draft'?'—':pct(c.contacted/Math.max(1,c.targeted))}</td><td>${c.status==='Draft'?'—':pct(c.clicks/Math.max(1,c.delivered))}</td><td>${c.status==='Draft'?'—':pct(c.conversions/Math.max(1,c.delivered))}</td><td>${c.status==='Draft'?'—':money(c.revenue)}</td><td><button onclick="campaignDetail(${c.id})">Inspect ↗</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Create your first simulated campaign.</td></tr>'}</tbody></table></div><div class="section-heading spaced"><div><h2>Reorder conversion comparison</h2><p>Simulated reorders / delivered messages</p></div></div><div class="comparison-list">${campaigns.filter(c=>c.status==='Simulated').map(c=>`<button onclick="campaignDetail(${c.id})"><span>${esc(c.name)}</span><i><em style="width:${c.conversions/Math.max(1,c.delivered)*100}%"></em></i><b>${pct(c.conversions/Math.max(1,c.delivered))}</b></button>`).join('')||'<div class="empty">Run a campaign simulation to compare response rates.</div>'}</div>`}
function campaignDetail(id){const c=campaigns.find(c=>c.id===id);openDrawer(`<div class="drawer-head"><h2>Campaign details</h2><button onclick="closeDrawer()">Close</button></div><div class="profile-title"><div><h2>${esc(c.name)}</h2><small>${esc(c.type)} · ${c.created}</small></div></div><div class="method-note">All delivery, click, and revenue outcomes below are simulated.</div>${c.status==='Draft'?`<button class="primary" onclick="runCampaign(${id});closeDrawer()">Run simulation</button>`:recordTable([{Metric:'Customers targeted',Value:fmt(c.targeted)},{Metric:'Contacted',Value:fmt(c.contacted)},{Metric:'Delivered',Value:fmt(c.delivered)},{Metric:'Clicks',Value:fmt(c.clicks)},{Metric:'Reorders',Value:fmt(c.conversions)},{Metric:'Simulated revenue',Value:money(c.revenue)},{Metric:'Cost per reorder',Value:money(c.cost/Math.max(1,c.conversions))},{Metric:'Incremental retention',Value:'Not measured'}])}`)}
const baseCohort=cohort;
function cohortDesign(){let html=baseCohort();html=html.replace('<div class="panel table-panel">',`${tabs(['purchase','revenue'],cohortMode,'cohortMode')}<div class="panel table-panel">`);if(cohortMode==='purchase')return html;const rows=cohortRows();return header('Cohort analysis','Revenue retained relative to each cohort’s acquisition month.',false)+tabs(['purchase','revenue'],cohortMode,'cohortMode')+`<div class="scope-bar"><span>Same product and channel selection as the purchase heatmap</span><button onclick="cohortMode='purchase';renderContent()">Change cohort filters</button></div><div class="table-wrap ledger"><table class="heat"><thead><tr><th>Cohort</th>${Array.from({length:7},(_,i)=>`<th>Month ${i}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>{const cs=customers.filter(c=>c.completed[0]?.date.slice(0,7)===r.month&&(!cohortChannel||c.channel===cohortChannel)&&(!cohortProduct||c.product===Number(cohortProduct)-1)),revenues=Array.from({length:7},(_,i)=>{const d=date(r.month+'-01'),month=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+i,1)).toISOString().slice(0,7);return cs.flatMap(c=>c.completed).filter(o=>o.date.startsWith(month)).reduce((s,o)=>s+o.amount,0)});return `<tr><td>${r.month}</td>${r.values.map((v,i)=>v==null?'<td>—</td>':`<td title="${money(revenues[i])} completed revenue" style="background:rgba(47,105,94,${.04+Math.min(1,revenues[i]/Math.max(1,revenues[0]))*.62})">${pct(revenues[i]/Math.max(1,revenues[0]))}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><p class="forecast-note">Completed revenue in each month / month-zero revenue. Cells may exceed 100%. Unfinished observation months remain blank.</p>`}
const baseProducts=productsView;
function productsDesign(){return baseProducts().replace('<div class="two-grid">','<div class="two-grid product-comparison">').replace('<div class="notice">','<div class="method-note compact">')}
const baseChurn=churnIntelligence;
function churnDesign(){let html=baseChurn();const start=html.indexOf('<div class="analysis-box">'),forecast=html.indexOf('<div class="panel"><div class="panel-head"><div><h2>Commercial inactivity outlook');const section=html.indexOf('<div class="section-rule"><h2>Daily order anomaly monitor');const heading=header('Churn intelligence','Ask, investigate, and act on evidence from your customer records.');if(churnTab==='Signals')return heading+tabs(['Analysis','Signals'],churnTab,'churnTab')+insightPanel()+html.slice(forecast>=0?forecast:section);return heading+tabs(['Analysis','Signals'],churnTab,'churnTab')+`<div class="analyst-layout"><section>${html.slice(start,html.indexOf('</div></div>',start)+12)}</section><aside class="query-sidebar"><h3>Recent analyses</h3>${recentQueries.map((q,i)=>`<button onclick="document.getElementById('question').value=recentQueries[${i}];askQuestion()">${esc(q)}</button>`).join('')||'<p>Your questions will appear here after you run an analysis.</p>'}<div class="provenance"><b>Connected evidence</b><p>${fmt(customers.length)} synthetic customers<br>${fmt(D.orders.length)} orders<br>As of ${D.asOf}</p><small>Answers use approved metrics. Unsupported questions are identified explicitly.</small></div></aside></div>`}
askQuestion=async function(e){e?.preventDefault();const q=document.getElementById('question').value.trim();if(!q)return;const target=document.getElementById('answer');target.setAttribute('aria-live','polite');target.innerHTML='<div class="query-loading"><div class="skeleton"></div><div class="skeleton"></div><span>Calculating from the selected records…</span></div>';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(!target.isConnected)return;target.innerHTML=answerQuestion(q);recentQueries=[q,...recentQueries.filter(x=>x!==q)].slice(0,6);put('queries',recentQueries);if(/product|categor/i.test(q))target.insertAdjacentHTML('beforeend',`<div class="comparison-list">${productEvidence().map(r=>`<div><span>${r.product}</span><i><em style="width:${r.inactivity*100}%"></em></i><b>${pct(r.inactivity)}</b></div>`).join('')}</div>`)};
function modelDesign(){const m=D.model,r=m.metrics[m.selected];let body='';if(modelTab==='Performance')body=`<div class="metric-band">${summaryMetric('Precision',pct(r.precision),'Held-out test')}${summaryMetric('Recall',pct(r.recall),'Held-out test')}${summaryMetric('PR-AUC',pct(r.pr_auc),'Precision–recall area')}${summaryMetric('ROC-AUC',pct(r.roc_auc),'Ranking discrimination')}</div><div class="supporting-metrics"><span>F1 <b>${pct(r.f1)}</b></span><span>Precision at ${r.capacity} <b>${pct(r.precision_at_k)}</b></span><span>Recall at ${r.capacity} <b>${pct(r.recall_at_k)}</b></span><span>Lift <b>${r.lift.toFixed(2)}×</b></span></div><div class="two-grid model-grid">${panel('Confusion matrix','Actual rows · predicted columns',`<div class="matrix">${[['True negatives',r.confusion[0][0]],['False positives',r.confusion[0][1]],['False negatives',r.confusion[1][0]],['True positives',r.confusion[1][1]]].map(([n,v])=>`<div><small>${n}</small><b>${v}</b></div>`).join('')}</div>`)}${panel('Calibration reliability',`Brier loss ${r.brier.toFixed(3)} · lower is better`,recordTable(r.calibration.map(([p,o])=>({'Predicted':pct(p),'Observed':pct(o),'Gap':((p-o)*100).toFixed(1)+' pp'}))))}</div><div class="section-heading"><h2>Model comparison</h2><small>Selected by validation PR-AUC</small></div>${recordTable(Object.entries(m.metrics).map(([name,v])=>({Model:name,Recall:pct(v.recall),'PR-AUC':pct(v.pr_auc),'Brier loss':v.brier.toFixed(3),Status:name===m.selected?'Active':'Baseline'})))}<div class="method-note"><b>Prediction target</b><p>${esc(m.target)}</p><small>Evaluation threshold ${pct(m.threshold)} · train / validation / test: ${m.splitCounts.join(' / ')}. Synthetic performance does not establish production performance.</small></div>`;else if(modelTab==='Monitoring')body=`<div class="section-heading"><h2>Feature drift & completeness</h2><small>Current eligible population vs training</small></div>${recordTable(m.monitoring.map(f=>({Feature:f.feature,'Missing':pct(f.missing_rate),'Mean shift / σ':f.standardised_shift.toFixed(2),Status:f.standardised_shift>1?'Review shift':'Within threshold'})))}<div class="section-heading spaced"><h2>Current prediction distribution</h2></div>${compactDistribution(customers)}<p class="forecast-note">Historical score-distribution changes and delayed-label performance are unavailable.</p>`;else body=`<div class="section-heading"><h2>Active model record</h2><button onclick="trainingInfo()">Training controls</button></div>${recordTable([{Field:'Version',Value:m.version},{Field:'Model',Value:m.selected},{Field:'Trained',Value:m.trained},{Field:'Dataset',Value:m.dataset_version},{Field:'Features',Value:m.features.length},{Field:'Scored customers',Value:m.scored},{Field:'Release gate',Value:m.accepted?'Passed':'Not passed'}])}<div class="method-note"><b>Data availability</b><p>${esc(m.unavailable.join(' · '))}</p><p>${esc(m.explanation)}</p></div>${recordTable(m.subgroups.map(s=>({Product:s.product,Sample:s.population,'Precision':pct(s.precision),'Recall':pct(s.recall),'PR-AUC':pct(s.pr_auc)})))}`;return header('Model intelligence','A transparent view of model quality and operational health.',false)+`<div class="model-status"><span class="badge">Active model</span><code>${m.version}</code><span>${m.selected}</span><span>${m.horizon}-day horizon</span></div>`+tabs(['Performance','Monitoring','Model record'],modelTab,'modelTab')+body}
const reportDefs=[['summary','Executive summary','Business health'],['customers','Customer intelligence','Customer operations'],['products','Product performance','Commercial analytics'],['cohorts','Cohort retention','Lifecycle analytics'],['interventions','Intervention outcomes','Customer operations'],['monthly','Monthly churn & revenue','Business health']];
function reportPreview(){if(reportChoice==='summary')return (()=>{const m=metrics(scoped());return [{Metric:'Active customers',Value:fmt(m.active)},{Metric:'At-risk customers',Value:fmt(m.riskn)},{Metric:'Predicted inactivity',Value:pct(m.pred)},{Metric:'Observed retention',Value:pct(m.retention)},{Metric:'Repeat purchase rate',Value:pct(m.repeat)},{Metric:'Historical value per customer',Value:money(m.clv)},{Metric:'Revenue exposure',Value:money(m.atrisk)},{Metric:'Repeat-order revenue',Value:money(m.retained)}]})();if(reportChoice==='customers')return filtered().slice(0,8).map(c=>({Customer:c.code,Name:c.name,Risk:c.risk,Revenue:money(c.revenue)}));if(reportChoice==='products')return productRows().map(p=>({Product:p.name,Customers:p.customers,Retention:pct(p.retention),Revenue:money(p.revenue)}));if(reportChoice==='cohorts')return cohortRows().slice(-6).map(r=>({Month:r.month,Customers:r.size,'Month 1':r.values[1]==null?'Not mature':pct(r.values[1])}));if(reportChoice==='interventions')return interventions.slice(0,8).map(i=>({Customer:customers[i.customer].code,Status:i.status,Owner:i.assignee}));return series(scoped()).map(s=>({Month:s.label,Retention:pct(s.retention),Revenue:money(s.retained)}))}
function reportsDesign(){return header('Reports','Review the evidence before you share it.')+`<div class="report-workspace"><aside class="report-library"><h3>REPORT LIBRARY</h3>${reportDefs.map(([id,n,cat])=>`<button class="${reportChoice===id?'active':''}" onclick="reportChoice='${id}';renderContent()"><span>${n}</span><small>${cat}</small></button>`).join('')}<h3 class="spaced">RECENT EXPORTS</h3>${reportHistory.slice(0,4).map(r=>`<p class="export-record">${esc(r.name)}<small>${esc(r.at)}</small></p>`).join('')||'<p class="forecast-note">Exported reports appear here.</p>'}</aside><section class="report-preview"><div class="section-heading"><div><h2>${reportDefs.find(r=>r[0]===reportChoice)[1]}</h2><p>Preview · ${period}-day reporting window · synthetic records</p></div><button class="primary" onclick="generateReport()">Download CSV</button></div>${recordTable(reportPreview())}<div class="preview-footer">Preview ready · large reports show a sample. The download includes all matching records.</div><div class="method-note"><b>Export scope</b><p>Customer exports retain customer workspace filters. Product reports use the acquisition window. Cohorts retain product and channel filters. Model risk is an estimate; intervention outcomes are observational.</p></div></section></div>`}
function generateReport(){if(!reportPreview().length){toast("No matching records to export.");return}exportReport(reportChoice);reportHistory.unshift({name:reportDefs.find(r=>r[0]===reportChoice)[1],at:new Date().toLocaleString('en-IN')});put('report-history',reportHistory.slice(0,12));renderContent()}
const oldClose=closeDrawer;let drawerTrigger;
const oldOpen=openDrawer;
openDrawer=function(html){drawerTrigger=document.activeElement;oldOpen(html);document.querySelector('.drawer')?.setAttribute('tabindex','-1')};
closeDrawer=function(){const bg=document.querySelector('.overlay-backdrop');if(!bg)return;bg.classList.add('leaving');const trigger=drawerTrigger;setTimeout(()=>{oldClose();if(trigger?.isConnected)trigger.focus()},matchMedia('(prefers-reduced-motion: reduce)').matches?0:180)};
renderContent=function(){const renders={'Overview':overviewDesign,'Customer Intelligence':customersDesign,'Churn Intelligence':churnDesign,'Customer Segments':segmentsDesign,'Retention Actions':actionsDesign,'Campaign Intelligence':campaignsDesign,'Cohort Analysis':cohortDesign,'Product Analytics':productsDesign,'Model Intelligence':modelDesign,'Reports':reportsDesign,'Settings':settingsView};const el=document.getElementById('content');el.dataset.view=view;el.innerHTML=renders[view]().replaceAll('Browser-local demonstration records',apiMode?'Database-backed demonstration records':'Browser-local demonstration records').replaceAll('Interventions and outcomes in this hosted demo are stored in your browser.',apiMode?'Interventions and outcomes are stored in the database.':'Interventions and outcomes in this hosted demo are stored in your browser.')+`<footer class="page-foot"><span>Retention Radar <span class="foot-sep">/</span> Synthetic workspace</span><span>Detect → Understand → Prioritise → Intervene → Measure → Learn</span></footer>`;el.classList.remove('view-enter');if(view==='Cohort Analysis'){const rows=cohortRows();el.querySelectorAll('.heat tbody tr').forEach((row,i)=>{row.tabIndex=0;row.title='Inspect cohort '+rows[i].month;row.style.cursor='pointer';row.onclick=()=>inspectCohort(rows[i].month);row.onkeydown=e=>{if(e.key==='Enter')row.click()}})}requestAnimationFrame(()=>el.classList.add('view-enter'))};

document.addEventListener('keydown',event=>{if(event.target.getAttribute?.('role')==='tab'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const ts=[...event.target.parentElement.querySelectorAll('[role=tab]')],i=ts.indexOf(event.target),next=ts[(i+(event.key==='ArrowRight'?1:ts.length-1))%ts.length];next.click();document.querySelector('[role=tab][aria-selected=true]')?.focus()}});

function inspectCohort(month){const cs=customers.filter(c=>c.completed[0]?.date.slice(0,7)===month&&(!cohortChannel||c.channel===cohortChannel)&&(!cohortProduct||c.product===Number(cohortProduct)-1));openDrawer(`<div class="drawer-head"><h2>${month} acquisition cohort</h2><button onclick="closeDrawer()">Close</button></div><p class="section-intro">${cs.length} customers · first completed purchase in ${month}. Showing the first 30 records.</p>${customerTable(cs.slice(0,30),'Cohort customers','Select a customer to inspect their journey',false,true)}`)}
